// Calculate week date range
const now = new Date();
const day = now.getDay();
const diff = (day === 0 ? -6 : 1 - day); // Monday
const monday = new Date(now);
monday.setDate(now.getDate() + diff);
monday.setHours(0, 0, 0, 0);
const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);
friday.setHours(23, 59, 59, 999);

return [{
  json: {
    repo: $env.GITHUB_REPO || 'owner/repo',
    github_api_url: 'https://api.github.com',
    week_start: monday.toISOString(),
    week_end: friday.toISOString(),
    language: $env.SUMMARY_LANGUAGE || 'EN',
    destination: $env.DESTINATION_TYPE || 'discord'
  }
}];

// Format all GitHub data into a prompt for Claude
const commits = $input.first().json;
const issues = $input.all()[1]?.json;
const prs = $input.all()[2]?.json;

const lang = $env.SUMMARY_LANGUAGE || 'EN';
const repo = $env.GITHUB_REPO || 'owner/repo';

// Safely extract arrays
const commitList = Array.isArray(commits) ? commits : (commits.data ? commits.data : []);
const issueList = Array.isArray(issues) ? issues : (issues.data ? issues.data : []);
const prList = Array.isArray(prs) ? prs : (prs.data ? prs.data : []);

// Filter PRs to only merged ones
const mergedPrs = prList.filter(pr => pr.merged_at);

// Filter out pull requests from issues (GitHub returns PRs in issues endpoint)
const realIssues = issueList.filter(i => !i.pull_request);

const prompt = lang === 'FR' ? `
Génère un résumé narratif hebdomadaire pour le dépôt GitHub **${repo}**.

## Données de cette semaine :

### Commits (${commitList.length})
${commitList.slice(0, 30).map((c, i) => `${i+1}. ${c.commit?.message?.split('\n')[0] || 'no message'} — ${c.commit?.author?.name || 'unknown'}`).join('\n')}
${commitList.length > 30 ? `... et ${commitList.length - 30} autres commits` : ''}

### Issues fermées (${realIssues.length})
${realIssues.slice(0, 20).map((i, j) => `${j+1}. #${i.number} ${i.title}`).join('\n')}
${realIssues.length > 20 ? `... et ${realIssues.length - 20} autres` : ''}

### Pull Requests fusionnées (${mergedPrs.length})
${mergedPrs.slice(0, 20).map((p, k) => `${k+1}. #${p.number} ${p.title} (${p.merged_by?.login || 'unknown'})`).join('\n')}
${mergedPrs.length > 20 ? `... et ${mergedPrs.length - 20} autres` : ''}

## Instructions :
- Rédige un résumé professionnel et engageant en français
- Groupe les informations par thème quand c'est pertinent
- Mentionne les contributions notables par nom d'auteur
- Inclus une section "À retenir" avec les points clés
- Sois concis mais complet (max 500 mots)
` : `
Generate a narrative weekly summary for the GitHub repository **${repo}**.

## This Week's Data:

### Commits (${commitList.length})
${commitList.slice(0, 30).map((c, i) => `${i+1}. ${c.commit?.message?.split('\n')[0] || 'no message'} — ${c.commit?.author?.name || 'unknown'}`).join('\n')}
${commitList.length > 30 ? `... and ${commitList.length - 30} more commits` : ''}

### Closed Issues (${realIssues.length})
${realIssues.slice(0, 20).map((i, j) => `${j+1}. #${i.number} ${i.title}`).join('\n')}
${realIssues.length > 20 ? `... and ${realIssues.length - 20} more` : ''}

### Merged Pull Requests (${mergedPrs.length})
${mergedPrs.slice(0, 20).map((p, k) => `${k+1}. #${p.number} ${p.title} (${p.merged_by?.login || 'unknown'})`).join('\n')}
${mergedPrs.length > 20 ? `... and ${mergedPrs.length - 20} more` : ''}

## Instructions:
- Write a professional and engaging summary in English
- Group information thematically when relevant
- Notable contributions by author name
- Include a "Key Takeaways" section with the main points
- Be concise but comprehensive (max 500 words)
`;

return [{
  json: {
    prompt: prompt,
    meta: {
      total_commits: commitList.length,
      total_issues: realIssues.length,
      total_merged_prs: mergedPrs.length,
      repo: repo,
      language: lang
    }
  }
}];

